from collections import deque
R,C=len(grid),len(grid[0])
out=[row[:] for row in grid]
q=deque()
for r in range(R):
 for c in range(C):
  if grid[r][c]==9:
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     rr,cc=r+dr,c+dc
     if 0<=rr<R and 0<=cc<C and grid[rr][cc]==0 and out[rr][cc]==0:
      out[rr][cc]=9; q.append((rr,cc))
while q:
 r,c=q.popleft()
 for dr in (-1,0,1):
  for dc in (-1,0,1):
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and grid[rr][cc]==0 and out[rr][cc]==0:
    out[rr][cc]=9;q.append((rr,cc))
print('flooded',sum(x==9 for row in out for x in row)-sum(x==9 for row in grid for x in row))
print('\n'.join(' '.join(map(str,row)) for row in out))

def fill_conn(G,color,neighbors):
 O=[row[:] for row in G]; q=deque()
 for r in range(len(G)):
  for c in range(len(G[0])):
   if G[r][c]==color:
    for dr,dc in neighbors:
     rr,cc=r+dr,c+dc
     if 0<=rr<len(G) and 0<=cc<len(G[0]) and G[rr][cc]==0 and O[rr][cc]==0:
      O[rr][cc]=color;q.append((rr,cc))
 while q:
  r,c=q.popleft()
  for dr,dc in neighbors:
   rr,cc=r+dr,c+dc
   if 0<=rr<len(G) and 0<=cc<len(G[0]) and G[rr][cc]==0 and O[rr][cc]==0:
    O[rr][cc]=color;q.append((rr,cc))
 return O
