 print(len(diffs), 'of output target',sum(E[r][c]==3 and D[r][c]==0 for r in range(20) for c in range(21)), 'of predicted',sum(O[r][c]==3 and D[r][c]==0 for r in range(20) for c in range(21)))
 print(diffs[:25])

